Generate documentation for this C function:

**Function**: stack_to_string

```c
// C program for the function called stack_to_string
// Contains target function implementation and dependency signatures

#include <stdio.h>     /// for IO operations
#include <stdlib.h>  /// for including functions involving memory allocation such as `malloc`
#include <string.h>  /// for string operations

struct DArrayStack
{
    int capacity, top;  ///< to store capacity and top of the stack
    int *arrPtr;        ///< array pointer
};

// Target function implementation
int stack_to_string(DArrayStack *ptr, char *buffer, int buffer_size)
{
    if (buffer == NULL || buffer_size <= 0)
    {
        return -1;
    }
    if (ptr == NULL || ptr->top == -1)
    {
        if (buffer_size >= 3)
        {
            strcpy(buffer, "[]");
            return 2;
        }
        return -1;
    }

    int written = 0;
    int remaining = buffer_size - 1;

    buffer[written++] = '[';
    remaining--;

    for (int i = 0; i <= ptr->top && remaining > 0; i++)
    {
        char num_buf[32];
        int num_len = snprintf(num_buf, sizeof(num_buf), "%d", ptr->arrPtr[i]);

        if (i > 0)
        {
            if (remaining < 2)
            {
                break;
            }
            buffer[written++] = ',';
            buffer[written++] = ' ';
            remaining -= 2;
        }

        if (num_len > remaining)
        {
            break;
        }

        memcpy(buffer + written, num_buf, num_len);
        written += num_len;
        remaining -= num_len;
    }

    if (remaining >= 1)
    {
        buffer[written++] = ']';
    }
    buffer[written] = '\0';

    return written;
}

```

